        bool zeroReverted;
        try c.transferOwnership(address(0)) { zeroReverted = false; } catch { zeroReverted = true; }

        // Owner before the valid transfer must still be this test contract (deployer).
        address ownerBefore = c.owner();

        // Valid ownership transfer.
